(function(){'use strict';
const root=document.documentElement,main=document.querySelector('.envelope-frame'),catalog=window.WeylandChapters||[],space=document.createElement('div');space.id='product-space';space.setAttribute('aria-label','Product pages in the 3D space');document.body.appendChild(space);let reading=null,returnFocus=null,latest=null;const pages=[];
function button(label,fn){const b=document.createElement('button');b.type='button';b.textContent=label;b.addEventListener('click',fn);return b}
function close(){if(!reading)return;reading.classList.remove('is-reading');reading=null;root.classList.remove('product-reading');main.inert=false;pages.forEach(p=>p.el.inert=true);if(latest)place(latest);if(returnFocus&&returnFocus.isConnected)returnFocus.focus({preventScroll:true});}
function open(page){returnFocus=document.activeElement;if(reading)reading.classList.remove('is-reading');reading=page.el;root.classList.add('product-reading');main.inert=true;window.__weylandWorldInput?.clear();pages.forEach(p=>p.el.inert=p!==page);reading.classList.add('is-reading');reading.style.visibility='';page.logo.focus({preventScroll:true});page.update();}
function escape(e){if(e.key==='Escape'&&reading){e.preventDefault();e.stopImmediatePropagation();close();}}document.addEventListener('keydown',escape,true);
for(const [i,c]of catalog.entries()){if(i===0)continue;const source=document.getElementById(c.id);if(!source)continue;const label=c.label.replace(' · Planned',''),title=source.querySelector('h2,h3')?.textContent.trim()||label,paragraphs=[...source.querySelectorAll('p')].map(p=>p.textContent.trim()).filter(Boolean);const el=document.createElement('article');el.className='product-plane';el.tabIndex=-1;el.inert=true;el.setAttribute('aria-label',label+' by WeylandAI');el.dataset.productPage=c.id;const nav=document.createElement('nav');nav.setAttribute('aria-label',label+' feature chapters');el.appendChild(nav);const page={id:c.id,el,index:pages.length};const logo=button(label+' by WeylandAI',()=>el.scrollTo({top:0,behavior:'smooth'}));logo.className='product-logo';page.logo=logo;nav.appendChild(logo);const featureNames={huntx:['Search & filter','Source review'],takeoffx:['Opening counts','Source trace'],propx:['Scope & pricing','Proposal preview'],contractx:['Planned handoff'],cutsheetx:['Catalog matching','Coverage'],subx:['Schedule','Page evidence','Packet'],sightx:['Source geometry','Hardware walk'],meetingx:['Project room','Room record'],wire:['Headlines','Publisher links']};const chapterNames=['Overview',...(featureNames[c.id]||['Workflow']),'Workspace'],sections=[],tabs=[];
chapterNames.forEach((name,n)=>{const section=document.createElement('section');section.id='product-'+c.id+'-'+n;section.dataset.chapter=String(n);const number=document.createElement('div');number.className='chapter-number';number.textContent=String(n).padStart(2,'0')+' / '+name.toUpperCase();const heading=document.createElement('h2');heading.textContent=n===0?title:name;section.append(number,heading);const text=document.createElement('p');text.textContent=n===0?(paragraphs[0]||'Explore '+label+' in the WeylandAI workflow.'):n<chapterNames.length-1?(paragraphs[n]||paragraphs[0]||'Return to the main page for the current workflow and available controls.'):'The current product workspace remains on the main WeylandAI page. Open it there to keep your existing session and project context.';section.appendChild(text);if(n===chapterNames.length-1){section.appendChild(button('Open existing '+label+' workspace',()=>{close();window.__weylandWorldInput?.clear();document.getElementById('envelope-raise')?.click();source.scrollIntoView({behavior:'smooth',block:'start'});}));}section.appendChild(button('Return to WeylandAI',close));el.appendChild(section);sections.push(section);const tab=button(name,()=>el.scrollTo({top:section.offsetTop-nav.offsetHeight,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'}));nav.appendChild(tab);tabs.push(tab);});
page.update=()=>{let n=0;sections.forEach((s,i)=>{if(s.offsetTop<=el.scrollTop+nav.offsetHeight+40)n=i});tabs.forEach((t,i)=>{if(i===n)t.setAttribute('aria-current','page');else t.removeAttribute('aria-current')});logo.setAttribute('aria-current',n===0?'page':'false');el.dataset.activeChapter=String(n);};el.addEventListener('scroll',page.update,{passive:true});space.appendChild(el);pages.push(page);page.update();const enter=button('Explore '+label+' in 3D',()=>open(page));enter.className='button product-entry';source.querySelector('h2,h3')?.insertAdjacentElement('afterend',enter);}
const chooser=document.createElement('label');chooser.id='product-world-menu';chooser.textContent='Read a product page';const select=document.createElement('select');select.setAttribute('aria-label','Choose a product to read');const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent='Choose product…';select.appendChild(placeholder);for(const p of pages){const o=document.createElement('option');o.value=p.id;o.textContent=p.logo.textContent;select.appendChild(o)}select.addEventListener('change',()=>{const p=pages.find(p=>p.id===select.value);if(p)open(p);select.value=''});chooser.appendChild(select);document.body.appendChild(chooser);
// Shared camera projection: world-space metres -> camera basis -> CSS pixels, then four-corner homography.
function solve(A,b){for(let i=0;i<8;i++){let k=i;for(let j=i+1;j<8;j++)if(Math.abs(A[j][i])>Math.abs(A[k][i]))k=j;if(Math.abs(A[k][i])<1e-9)return null;[A[i],A[k]]=[A[k],A[i]];[b[i],b[k]]=[b[k],b[i]];for(let j=i+1;j<8;j++){const f=A[j][i]/A[i][i];for(let q=i;q<8;q++)A[j][q]-=f*A[i][q];b[j]-=f*b[i]}}const x=[];for(let i=7;i>=0;i--){let v=b[i];for(let j=i+1;j<8;j++)v-=A[i][j]*x[j];x[i]=v/A[i][i]}return x}
function place(detail){latest=detail;const cam=detail.camera,bd=document.querySelector('#stage-backdrop iframe');if(!bd||!cam)return;const r=bd.getBoundingClientRect(),vw=detail.viewport?.[0]||bd.clientWidth,vh=detail.viewport?.[1]||bd.clientHeight,sx=r.width/vw,sy=r.height/vh,f=cam.direction,u=cam.up,right=[u[1]*f[2]-u[2]*f[1],u[2]*f[0]-u[0]*f[2],u[0]*f[1]-u[1]*f[0]],dot=(a,b)=>a.reduce((v,x,i)=>v+x*b[i],0);for(const p of pages){if(reading===p.el)continue;const side=p.index%2?1:-1,row=Math.floor(p.index/2),X=side*1.35,Y=.8,Z=2.5+row*3;if(Z-cam.position[2]>6){p.el.style.visibility='hidden';p.el.inert=true;continue}const corners=[[-.45,.65],[.45,.65],[.45,-.65],[-.45,-.65]].map(([x,y])=>{const v=[X+x,Y+y,Z].map((q,i)=>q-cam.position[i]),z=dot(v,f);return z<=.1?null:[r.left+(1+dot(v,right)/z/.62/(vw/vh))*vw/2*sx,r.top+(1-dot(v,u)/z/.62)*vh/2*sy]});if(corners.some(q=>!q)){p.el.style.visibility='hidden';p.el.inert=true;continue}const A=[],b=[],src=[[0,0],[360,0],[360,470],[0,470]];src.forEach(([x,y],i)=>{const[X,Y]=corners[i];A.push([x,y,1,0,0,0,-X*x,-X*y],[0,0,0,x,y,1,-Y*x,-Y*y]);b.push(X,Y)});const h=solve(A,b);if(!h)continue;p.el.style.transform='matrix3d('+[h[0],h[3],0,h[6],h[1],h[4],0,h[7],0,0,1,0,h[2],h[5],0,1].join(',')+')';p.el.style.visibility='';p.el.inert=true;}}
window.addEventListener('weyland:world-camera',e=>place(e.detail));window.WeylandProductSpace=Object.freeze({open:id=>{const p=pages.find(p=>p.id===id);if(p)open(p)},close,pages:pages.map(p=>p.id),chapterZero:catalog[0]?.id});
})();
